CREATE OR ALTER PROCEDURE dbo.SP_CREAR_EVALUACION  (        @LoteId             INT      , @TipoEvaluacionId   INT      , @Usuario            VARCHAR(100)      , @UsuarioEvaluador   VARCHAR(100) = NULL      , @EvaluacionPadreId  INT = NULL      , @MotivoReevaluacion VARCHAR(500) = NULL      , @Observacion        VARCHAR(MAX) = NULL  )  AS  BEGIN      SET NOCOUNT ON;      SET XACT_ABORT ON;        DECLARE            @Intento                   SMALLINT          , @EvaluacionId              INT          , @EstadoPendienteId         INT          , @EstadoTerminadaId         INT            , @CodigoLote                VARCHAR(20)          , @ProductoCodigo            VARCHAR(50)          , @VersionId                 INT            , @VersionFaseId             INT          , @VersionFaseOrden          INT          , @CodigoReferencia          VARCHAR(30)          , @FaseCodigo                VARCHAR(20)          , @EsFinal                   BIT            , @PadreVersionFaseId        INT          , @PadreResultadoGeneral     BIT          , @PadreEstadoEvaluacionId   INT            , @UltimaVersionFaseId       INT          , @UltimaVersionFaseOrden    INT          , @UltimoResultadoGeneral    BIT;          BEGIN TRY            BEGIN TRANSACTION;              /* =========================================================             1. OBTENER ESTADOS DE EVALUACION             ========================================================= */            SELECT              @EstadoPendienteId = EstadoEvaluacionId          FROM dbo.ESTADO_EVALUACION          WHERE Codigo = 'PENDIENTE';              SELECT              @EstadoTerminadaId = EstadoEvaluacionId          FROM dbo.ESTADO_EVALUACION          WHERE Codigo = 'TERMINADA';              IF @EstadoPendienteId IS NULL          BEGIN              RAISERROR(                  'No existe el estado PENDIENTE.',                  16,                  1              );          END;              IF @EstadoTerminadaId IS NULL          BEGIN              RAISERROR(                  'No existe el estado TERMINADA.',                  16,                  1              );          END;              /* =========================================================             2. VALIDAR LOTE Y OBTENER VERSION             ========================================================= */            SELECT                @CodigoLote     = L.CodigoLote              , @ProductoCodigo = L.ProductoCodigo              , @VersionId      = L.VersionId            FROM dbo.LOTE L WITH (UPDLOCK, HOLDLOCK)            WHERE L.LoteId = @LoteId            AND L.Estado = 'ACTIVO';              IF @CodigoLote IS NULL          BEGIN              RAISERROR(                  'El lote no existe o se encuentra inactivo.',                  16,                  1              );          END;              /* =========================================================             3. VALIDAR TIPO DE EVALUACION             ========================================================= */            IF NOT EXISTS          (              SELECT 1                FROM dbo.TIPO_EVALUACION                WHERE TipoEvaluacionId = @TipoEvaluacionId                AND Estado = 'ACTIVO'          )          BEGIN              RAISERROR(                  'El tipo de evaluación no existe o se encuentra inactivo.',                  16,                  1              );          END;              /* =========================================================             4. VALIDAR QUE NO EXISTA EVALUACION ABIERTA             ========================================================= */            IF EXISTS          (              SELECT 1                FROM dbo.EVALUACION E                INNER JOIN dbo.ESTADO_EVALUACION EE                  ON EE.EstadoEvaluacionId =                     E.EstadoEvaluacionId                WHERE E.LoteId = @LoteId                  AND EE.Codigo IN                (                    'PENDIENTE',                    'EN_PROCESO'                )                  AND E.Estado = 'ACTIVO'          )          BEGIN              RAISERROR(                  'El lote ya posee una evaluación abierta.',                  16,                  1              );          END;              /* =========================================================             5. RESOLVER VERSIONFASE               DOS CAMINOS:               A) REEVALUACION                EvaluacionPadreId informado.                Debe permanecer en la misma etapa.               B) EVALUACION NORMAL                Debe determinar automáticamente la siguiente                etapa pendiente.             ========================================================= */              /* =========================================================             5A. REEVALUACION             ========================================================= */            IF @EvaluacionPadreId IS NOT NULL          BEGIN                SELECT                    @PadreVersionFaseId      = E.VersionFaseId                  , @PadreResultadoGeneral  = E.ResultadoGeneral                  , @PadreEstadoEvaluacionId =                      E.EstadoEvaluacionId                FROM dbo.EVALUACION E                WHERE E.EvaluacionId =                    @EvaluacionPadreId                  AND E.LoteId =                    @LoteId                  AND E.Estado =                    'ACTIVO';                  IF @PadreEstadoEvaluacionId IS NULL              BEGIN                  RAISERROR(                      'La evaluación padre no existe, está inactiva o pertenece a otro lote.',                      16,                      1                  );              END;                  /* -----------------------------------------------------                 El padre debe estar terminado.                 ----------------------------------------------------- */                IF @PadreEstadoEvaluacionId <>                 @EstadoTerminadaId              BEGIN                  RAISERROR(                      'La evaluación padre debe encontrarse TERMINADA para generar una reevaluación.',                      16,                      1                  );              END;                  /* -----------------------------------------------------                 Solo se reevalúa una evaluación NO CONFORME.                 ----------------------------------------------------- */                IF @PadreResultadoGeneral IS NULL              BEGIN                  RAISERROR(                      'La evaluación padre todavía no posee resultado general.',                      16,                      1                  );              END;                  IF @PadreResultadoGeneral = 1              BEGIN                  RAISERROR(                      'No se puede generar una reevaluación sobre una evaluación CONFORME.',                      16,                      1                  );              END;                  SET @VersionFaseId =                  @PadreVersionFaseId;                  /* -----------------------------------------------------                 Si trabaja con etapas, validar que la etapa                 continúe perteneciendo a la versión del lote.                 ----------------------------------------------------- */                IF @VersionFaseId IS NOT NULL                 AND NOT EXISTS                 (                     SELECT 1                       FROM dbo.VERSIONFASE VF                       WHERE VF.VersionFaseId =                           @VersionFaseId                         AND VF.VersionId =                           @VersionId                         AND VF.Estado = 1                 )              BEGIN                  RAISERROR(                      'La etapa de la evaluación padre no pertenece a la versión del lote.',                      16,                      1                  );              END;            END              /* =========================================================             5B. EVALUACION NORMAL             ========================================================= */            ELSE          BEGIN                /* -----------------------------------------------------                 ¿La versión utiliza VERSIONFASE?                 ----------------------------------------------------- */                IF EXISTS              (                  SELECT 1                    FROM dbo.VERSIONFASE VF                    WHERE VF.VersionId =                        @VersionId                      AND VF.Estado = 1              )              BEGIN                    /* =================================================                     Buscar la última etapa evaluada del lote.                       Se considera únicamente evaluación TERMINADA                     asociada a una VERSIONFASE activa de esta versión.                     ================================================= */                    SELECT TOP (1)                          @UltimaVersionFaseId =                            E.VersionFaseId                        , @UltimaVersionFaseOrden =                            VF.Orden                        , @UltimoResultadoGeneral =                            E.ResultadoGeneral                    FROM dbo.EVALUACION E                    INNER JOIN dbo.VERSIONFASE VF                      ON VF.VersionFaseId =                         E.VersionFaseId                    WHERE E.LoteId =                        @LoteId                      AND E.Estado =                        'ACTIVO'                      AND E.EstadoEvaluacionId =                        @EstadoTerminadaId                      AND VF.VersionId =                        @VersionId                      AND VF.Estado = 1                    ORDER BY                        VF.Orden DESC                      , E.EvaluacionId DESC;                      /* =================================================                     CASO 1:                     Todavía no existe ninguna etapa evaluada.                       -> Primera etapa.                     ================================================= */                    IF @UltimaVersionFaseId IS NULL                  BEGIN                        SELECT TOP (1)                            @VersionFaseId =                              VF.VersionFaseId                        FROM dbo.VERSIONFASE VF                        WHERE VF.VersionId =                            @VersionId                          AND VF.Estado = 1                        ORDER BY                            VF.Orden                          , VF.VersionFaseId;                    END                    ELSE                  BEGIN                        /* =============================================                         CASO 2:                         Última etapa NO CONFORME.                           No puede avanzar normalmente.                           Debe generarse reevaluación indicando                         EvaluacionPadreId.                         ============================================= */                        IF @UltimoResultadoGeneral = 0                      BEGIN                            RAISERROR(                              'La última etapa evaluada quedó NO CONFORME. Debe generar una reevaluación indicando EvaluacionPadreId.',                              16,                              1                          );                        END;                          /* =============================================                         CASO 3:                         Última etapa todavía sin resultado general.                         ============================================= */                        IF @UltimoResultadoGeneral IS NULL                      BEGIN                            RAISERROR(                              'La última etapa evaluada todavía no posee resultado general.',                              16,                              1                          );                        END;                          /* =============================================                         CASO 4:                         Última etapa CONFORME.                           Buscar siguiente etapa.                         ============================================= */                        SELECT TOP (1)                            @VersionFaseId =                              VF.VersionFaseId                        FROM dbo.VERSIONFASE VF                        WHERE VF.VersionId =                            @VersionId                          AND VF.Estado = 1                          AND VF.Orden >                            @UltimaVersionFaseOrden                        ORDER BY                            VF.Orden                          , VF.VersionFaseId;                          /* =============================================                         Si no existe siguiente etapa, el recorrido                         de VERSIONFASE ya terminó.                         ============================================= */                        IF @VersionFaseId IS NULL                      BEGIN                            RAISERROR(                              'El lote ya completó todas las etapas configuradas de evaluación.',                              16,                              1                          );                        END;                    END;                END                ELSE              BEGIN                    /* =================================================                     LEGACY                       La versión todavía no tiene VERSIONFASE.                       Se mantiene VersionFaseId NULL.                     ================================================= */                    SET @VersionFaseId = NULL;                END;            END;              /* =========================================================             6. OBTENER DATOS DE LA ETAPA             ========================================================= */            IF @VersionFaseId IS NOT NULL          BEGIN                SELECT                    @VersionFaseOrden =                        VF.Orden                    , @CodigoReferencia =                        VF.CodigoReferencia                    , @FaseCodigo =                        F.Codigo                    , @EsFinal =                        VF.EsFinal                FROM dbo.VERSIONFASE VF                INNER JOIN dbo.FASE F                  ON F.FaseId =                     VF.FaseId                WHERE VF.VersionFaseId =                    @VersionFaseId                  AND VF.VersionId =                    @VersionId                  AND VF.Estado = 1;                  IF @VersionFaseOrden IS NULL              BEGIN                    RAISERROR(                      'No fue posible resolver la etapa de evaluación.',                      16,                      1                  );                END;                  /* -----------------------------------------------------                 Una etapa debe tener características.                 ----------------------------------------------------- */                IF NOT EXISTS              (                  SELECT 1                    FROM dbo.VERSIONCARACTERISTICA VC                    WHERE VC.VersionId =                        @VersionId                      AND VC.VersionFaseId =                        @VersionFaseId                      AND VC.Estado = 1              )              BEGIN                    RAISERROR(                      'La etapa seleccionada no contiene características activas para evaluar.',                      16,                      1                  );                END;            END;              /* =========================================================             7. CALCULAR INTENTO               Por ahora mantenemos la semántica existente:             correlativo general por lote.             ========================================================= */            SELECT              @Intento =                  ISNULL(MAX(Intento), 0) + 1            FROM dbo.EVALUACION            WHERE LoteId =                @LoteId;              /* =========================================================             8. CREAR EVALUACION PENDIENTE             ========================================================= */            INSERT INTO dbo.EVALUACION          (                LoteId              , EvaluacionPadreId              , TipoEvaluacionId              , EstadoEvaluacionId              , Intento              , FechaInicio              , FechaFin              , MotivoReevaluacion              , Observacion              , Estado              , AudUsuarioCreacion              , AudFechaCreacion              , UsuarioEvaluador              , ResultadoGeneral              , VersionFaseId          )          VALUES          (                @LoteId              , @EvaluacionPadreId              , @TipoEvaluacionId              , @EstadoPendienteId              , @Intento              , NULL              , NULL              , @MotivoReevaluacion              , @Observacion              , 'ACTIVO'              , @Usuario              , SYSDATETIME()              , @UsuarioEvaluador              , NULL              , @VersionFaseId          );              SET @EvaluacionId =              SCOPE_IDENTITY();              /* =========================================================             9. CONFIRMAR             ========================================================= */            COMMIT TRANSACTION;              /* =========================================================             10. RESPUESTA             ========================================================= */            SELECT                0 AS CodigoResultado                , CASE                      WHEN @EvaluacionPadreId IS NOT NULL                        THEN                        'Reevaluación creada correctamente para la misma etapa.'                      WHEN @VersionFaseId IS NULL                        THEN                        'Evaluación creada correctamente en modo legacy.'                      ELSE                        'Evaluación creada correctamente para la etapa correspondiente.'                  END AS Mensaje                , @EvaluacionId                  AS EvaluacionId                , @LoteId                  AS LoteId                , @CodigoLote                  AS CodigoLote                , @ProductoCodigo                  AS ProductoCodigo                , @VersionId                  AS VersionId                , @VersionFaseId                  AS VersionFaseId                , @VersionFaseOrden                  AS VersionFaseOrden                , @CodigoReferencia                  AS CodigoReferencia                , @FaseCodigo                  AS FaseCodigo                , @EsFinal                  AS EsFinal                , @EvaluacionPadreId                  AS EvaluacionPadreId                , @Intento                  AS Intento                , @UsuarioEvaluador                  AS UsuarioEvaluador                , 'PENDIENTE'                  AS EstadoEvaluacion;        END TRY      BEGIN CATCH            IF @@TRANCOUNT > 0              ROLLBACK TRANSACTION;            SELECT                -1 AS CodigoResultado              , ERROR_NUMBER() AS ErrorNumero              , ERROR_LINE() AS ErrorLinea              , ERROR_PROCEDURE() AS ErrorProcedimiento              , ERROR_MESSAGE() AS Mensaje;        END CATCH;    END;
GO
